    board = list(board_lines)
    if action not in {"UP", "DOWN", "LEFT", "RIGHT", "SPACE"}:
        return board

    mirror_pixel = board[0].find("S")
    if mirror_pixel < 0:
        return board

    mirror = mirror_pixel // 3
    marker = board[1][mirror_pixel + 1]

    def render(black, targets, mirror_col, mirror_selected, border):
        out = [["b"] * 64 for _ in range(64)]

        for r in range(64):
            out[r][63] = border[r]
        for c in range(63):
            out[63][c] = "B"

        def block(r, c, color, center=None):
            pr, pc = 3 * r, 3 * c
            for dr in range(3):
                for dc in range(3):
                    out[pr + dr][pc + dc] = color
            if center is not None:
                out[pr + 1][pc + 1] = center

        for r, c in targets:
            block(r, c, "Y")

        reflected = {(r, 2 * mirror_col - c) for r, c in black}
        for r, c in reflected:
            block(r, c, "c", "Y" if (r, c) in targets else None)

        for r, c in black:
            center = "b" if mirror_selected else "W"
            block(r, c, "B", center)

        for r in range(21):
            block(r, mirror_col, "S", "W" if mirror_selected else "b")

        return ["".join(row) for row in out]

    # The unmarked-mirror scene transitions to the canonical playable scene.
    if marker == "S":
        black = {
            (6, 15), (6, 16), (6, 17),
            (7, 17), (8, 17),
            (9, 17), (9, 18), (9, 19),
        }
        targets = {
            (14, 3), (14, 4), (14, 5),
            (15, 3), (16, 3),
            (17, 1), (17, 2), (17, 3),
        }
        return render(black, targets, 12, True, ["Y"] * 64)

    black = set()
    targets = set()
    for r in range(21):
        for c in range(21):
            pr, pc = 3 * r, 3 * c
            corner = board[pr][pc]
            if corner == "B":
                black.add((r, c))
            if corner == "Y":
                targets.add((r, c))
            elif corner == "c" and board[pr + 1][pc + 1] == "Y":
                targets.add((r, c))

    mirror_selected = marker == "W"

    if action == "SPACE":
        mirror_selected = not mirror_selected
    else:
        dr, dc = {
            "UP": (-1, 0),
            "DOWN": (1, 0),
            "LEFT": (0, -1),
            "RIGHT": (0, 1),
        }[action]

        if mirror_selected:
            if dr:
                return board
            mirror += dc
        else:
            black = {(r + dr, c + dc) for r, c in black}

        reflected = {(r, 2 * mirror - c) for r, c in black}
        if not 0 <= mirror < 21:
            return board
        if any(
