    for r in range(63):
        if border[r] == "Y":
            border[r] = "B"
            break

    return render(black, targets, mirror, mirror_selected, border)

import re


def _mouse_position(action):
    """Accept the documented mouse strings and common structured equivalents."""
    if isinstance(action, str):
        if not action.strip().upper().startswith("MOUSE"):
            return None
        numbers = re.findall(r"-?\d+", action)
        if len(numbers) >= 2:
            return int(numbers[0]), int(numbers[1])
        return None

    if isinstance(action, (tuple, list)):
        if len(action) == 3 and str(action[0]).upper() == "MOUSE":
            return int(action[1]), int(action[2])
        if len(action) == 2:
            if str(action[0]).upper() == "MOUSE":
                value = action[1]
                if isinstance(value, (tuple, list)) and len(value) == 2:
                    return int(value[0]), int(value[1])
            if all(isinstance(x, int) for x in action):
                return action[0], action[1]

    if isinstance(action, dict):
        name = action.get("type", action.get("name", action.get("action", "MOUSE")))
        if str(name).upper().startswith("MOUSE"):
            row = action.get("row", action.get("r"))
            col = action.get("col", action.get("c"))
            if row is not None and col is not None:
                return int(row), int(col)

    return None


