                b[16 + dy][22 + dx] = "c"

    # Lower control-bank backgrounds.
    rect(32, 50, 1, 30, "g")
    rect(32, 50, 32, 61, "W")

    # Three rows of horizontal control marks.
    for r in (33, 39, 45):
        for c in (7, 12, 17, 22):
            rect(r, r, c, c + 2, "B" if r == 33 else "w")
        for c in (38, 43, 48, 53):
            rect(r, r, c, c + 2, "w")

    # Three rows of vertical control marks.
    for r in (35, 41, 47):
        for c in (8, 13, 18, 23, 39, 44, 49, 54):
            rect(r, r + 2, c, c, "w")

    # Connecting lines.
    b[51][16] = "g"
    rect(52, 52, 11, 21, "g")
    b[53][11] = "g"
    b[53][21] = "g"

    b[51][58] = "W"
    rect(52, 52, 46, 58, "W")
    b[53][46] = "W"

    # Option boxes, first selected.
    outline(54, 62, 7, 15, "b")
    outline(54, 62, 17, 25, "g")

    rect(57, 59, 8, 9, "Y")
    b[58][11] = "W"
    b[58][13] = "W"

    rect(55, 56, 20, 22, "Y")
    b[58][21] = "W"
    b[60][21] = "W"

    # Blue circular button.
    for r in range(54, 63):
        half_width = 2 if r in (54, 62) else 3 if r in (55, 61) else 4
        rect(r, r, 46 - half_width, 46 + half_width, "b")

    return ["".join(row) for row in b]


def predict(board_lines, action):
    lines = list(board_lines)
    position = _mouse_position(action)
    if position is None:
        return lines

    row, col = position
    if not (0 <= row < 64 and 0 <= col < 64):
        return lines

    expanded = lines[3][1] == "G" and lines[3][32] == "W"

    if not expanded:
        # In the compact layout, clicking the blue circle opens/reset the UI.
        if 51 <= row <= 59 and 32 <= col <= 40:
            if lines[row][col] == "b":
                return _expanded_initial_board()
        return lines

    b = [list(line) for line in lines]

    # Every expanded-layout mouse click advances the status indicator.
    for c in range(61, 0, -1):
        if b[1][c] == "b":
            b[1][c] = "G"
            break

    # Right-bank horizontal marks.
    if row in (33, 39, 45):
        for c0 in (38, 43, 48, 53):
            if c0 <= col <= c0 + 2:
                color = "B" if b[row][c0] == "w" else "w"
                for c in range(c0, c0 + 3):
                    b[row][c] = color
                return ["".join(r) for r in b]

    # Right-bank vertical marks.
    if col in (39, 44, 49, 54):
        for r0 in (35, 41, 47):
            if r0 <= row <= r0 + 2:
                color = "B" if b[r0][col] == "w" else "w"
                for r in range(r0, r0 + 3):
                    b[r][col] = color
                return ["".join(r) for r in b]

    # Lower option selection.
    selected = None
    if 54 <= row <= 62:
        if 7 <= col <= 15:
            selected = 0
        elif 17 <= col <= 25:
            selected = 1

    if selected is not None:
        for option, c0 in enumerate((7, 17)):
            color = "b" if option == selected else "g"
            for c in range(c0, c0 + 9):
                b[54][c] = color
                b[62][c] = color
            for r in range(54, 63):
                b[r][c0] = color
                b[r][c0 + 8] = color

        # Erase the previous charcoal preview.
        for r in range(3, 32):
            for c in range(1, 31):
                if b[r][c] == "c":
                    b[r][c] = "G"

        if selected == 0:
            r0, c0 = 16, 6
            pattern = ("cccc", ".ccc", ".ccc", "cccc")
            left_mark_color = "w"
        else:
            r0, c0 = 8, 14
            pattern = ("c..c", "cccc", "cccc", "cccc")
            left_mark_color = "B"

        for dy, pattern_row in enumerate(pattern):
            for dx, value in enumerate(pattern_row):
                if value == "c":
                    b[r0 + dy][c0 + dx] = "c"

        for r in range(47, 50):
            for c in (8, 13, 18, 23):
                b[r][c] = left_mark_color

    # Other clicks, including the expanded blue button, have no additional
    # observed visible effect.
    return ["".join(r) for r in b]

