# Hidden state is required by the contradictory board-only transitions.
# Call predict chronologically, and reset before a separate replay.
_state = None


def reset_predictor():
    global _state
    _state = None


def _paint_tile(g, r, c, color):
    for rr in range(r, r + 3):
        for cc in range(c, c + 3):
            g[rr][cc] = color


def _yellow_tiles(r, c, stage):
    """r,c is the top-left of the yellow spine's uppermost tile."""
    tiles = [
        (0, 0, "Y"), (0, 1, "R"),
        (1, -1, "R"), (1, 0, "Y"),
        (2, 0, "Y"), (2, 1, "Y"), (2, 2, "R"),
    ]
    if stage == 0:
        tiles.append((3, 0, "W"))
    else:
        tiles.extend([(3, -1, "R"), (3, 0, "Y")])
        if stage == 1:
            tiles.append((4, 0, "W"))
        else:
            tiles.extend((4, x, "Y") for x in range(4))
            tiles.append((4, 4, "R"))
            if stage == 2:
                tiles.append((5, 0, "W"))
            else:
                tiles.extend([(5, -1, "R"), (5, 0, "Y")])
                if stage == 3:
                    tiles.append((6, 0, "W"))
                else:
                    tiles.extend((6, x, "Y") for x in range(3))
                    tiles.append((6, 3, "R"))
    return [(r + 3 * y, c + 3 * x, color)
            for y, x, color in tiles]


def _initial_purple_board():
    g = [["p"] * 64 for _ in range(64)]
    g[0][16:48] = ["c"] * 32

    # Corrected reset coordinates: right-hand figures were two columns left.
    sky = [(5, 53)]
    sky += [(r, c) for r in (8, 11, 14) for c in (47, 53)]
    sky += [(17, c) for c in (47, 50, 53)]

    green = [(r, c) for r in (38, 44, 50) for c in (5, 8, 11)]
    green += [(41, 5), (47, 5)]

    orange = [
        (47, 47), (50, 47), (50, 53),
        (53, 47), (53, 50), (53, 53),
    ]

    for r, c in sky + green + orange:
        _paint_tile(g, r, c, "c")

    # Corrected reset coordinate: yellow was one column left.
    for r, c, color in _yellow_tiles(14, 26, 0):
        _paint_tile(g, r, c, color)

    return g


def _component(g, start):
    r, c = start
    if not (1 <= r < 64 and 0 <= c < 64):
        return set()
    if g[r][c] == "p":
        return set()

    seen = {(r, c)}
    pending = [(r, c)]
    while pending:
        r, c = pending.pop()
        for rr, cc in ((r - 1, c), (r + 1, c),
                       (r, c - 1), (r, c + 1)):
            if (1 <= rr < 64 and 0 <= cc < 64
                    and (rr, cc) not in seen
                    and g[rr][cc] != "p"):
                seen.add((rr, cc))
                pending.append((rr, cc))
    return seen


def _active_component(g):
    for r in range(1, 64):
        for c in range(64):
            if g[r][c] in "YNSO":
                return _component(g, (r, c))
    return set()


def _tile_origins(component):
    r0 = min(r for r, c in component)
    c0 = min(c for r, c in component)
    return {
        (r0 + ((r - r0) // 3) * 3,
         c0 + ((c - c0) // 3) * 3)
        for r, c in component
    }


def _select(g, component):
    # Position identifies each figure in the recorded states.
    r0 = min(r for r, c in component)
    c0 = min(c for r, c in component)
    c1 = max(c for r, c in component)

    if r0 < 30:
        color = "Y" if c1 < 40 else "S"
    else:
        color = "N" if c0 < 30 else "O"

    # Preserve the indicator while deselecting the previous figure.
    for r in range(1, 64):
        for c in range(64):
            if g[r][c] in "YNSORW":
                g[r][c] = "c"

    units = _tile_origins(component)
    bottom = max(r for r, c in units)
    bottom_units = [(r, c) for r, c in units if r == bottom]

    frontier = (
        bottom_units[0]
        if color == "Y" and len(bottom_units) == 1
        else None
    )

    for r, c in units:
        degree = sum(
            neighbor in units
            for neighbor in ((r - 3, c), (r + 3, c),
                             (r, c - 3), (r, c + 3))
        )
        tile_color = "R" if degree == 1 else color
        if (r, c) == frontier:
            tile_color = "W"
        _paint_tile(g, r, c, tile_color)


def _move(g, component, dr, dc):
    if not component:
        return

    if any(
        not (1 <= r + dr < 64 and 0 <= c + dc < 64)
        or ((r + dr, c + dc) not in component
            and g[r + dr][c + dc] != "p")
        for r, c in component
    ):
        return

    old = [(r, c, g[r][c]) for r, c in component]
    for r, c, color in old:
        g[r][c] = "p"
    for r, c, color in old:
        g[r + dr][c + dc] = color


def _infer_phase(g):
    # Best-effort initialization for mid-replay calls.
    # Extension versus retraction cannot be inferred from the board alone.
    component = _active_component(g)
    if not component or not any(g[r][c] == "Y" for r, c in component):
        return 0

    units = _tile_origins(component)
    top = min(r for r, c in units)
    bottom = max(r for r, c in units)
    height = (bottom - top) // 3
    bottom_width = sum(r == bottom for r, c in units)

    if height == 3:
        return 0
    if height == 4:
        return 1
    if height == 5:
        return 2
    return 3 if bottom_width == 1 else 4


def predict(board_lines, action):
    """Return 64 next-board strings; exact replay requires chronological calls."""
    global _state

    board_lines = list(board_lines)
    if len(board_lines) != 64 or any(len(s) != 64 for s in board_lines):
        raise ValueError("Expected 64 strings, each containing 64 characters.")

    name = str(action).strip().upper()

    # The recorded blue-scene LEFT enters the purple scene.
    if board_lines[1][0] == "b" and name == "LEFT":
        _state = {"clock": 3, "phase": 0}
        return ["".join(row) for row in _initial_purple_board()]

    g = [list(row) for row in board_lines]
    if g[1][0] != "p":
        return board_lines

    if _state is None:
        _state = {
            "clock": 9 * g[0][16:48].count("W"),
            "phase": _infer_phase(g),
        }

    if name.startswith("MOUSE"):
        coordinates = re.findall(r"-?\d+", name)
        if len(coordinates) >= 2:
            r, c = map(int, coordinates[:2])
            component = _component(g, (r, c))
            if component:
                _select(g, component)

    elif name in ("UP", "DOWN", "LEFT", "RIGHT"):
        dr, dc = {
            "UP": (-3, 0),
            "DOWN": (3, 0),
            "LEFT": (0, -3),
            "RIGHT": (0, 3),
        }[name]
        _move(g, _active_component(g), dr, dc)

    elif name == "SPACE":
        component = _active_component(g)
        yellow = [(r, c) for r, c in component if g[r][c] == "Y"]

        if yellow:
            r0 = min(r for r, c in yellow)
            c0 = min(c for r, c in yellow)
            phase = (_state["phase"] + 1) % 8
            stage = min(phase, 8 - phase)
            tiles = _yellow_tiles(r0, c0, stage)

            destination = {
                (r + dy, c + dx)
                for r, c, color in tiles
                for dy in range(3)
                for dx in range(3)
            }

            allowed = all(
                1 <= r < 64 and 0 <= c < 64
                and ((r, c) in component or g[r][c] == "p")
                for r, c in destination
            )

            if allowed:
                for r, c in component:
                    g[r][c] = "p"
                for r, c, color in tiles:
                    _paint_tile(g, r, c, color)
                _state["phase"] = phase

    _state["clock"] += 2
    white = min(32, _state["clock"] // 9)
    g[0][16:48] = ["W"] * white + ["c"] * (32 - white)

    return ["".join(row) for row in g]

