# Raster entries: (row, starting_column, consecutive_colors).
_UPRIGHT = (
    [(24, 25, "g" * 14)]
    + [(r, 25, "g" + "p" * 12 + "g") for r in range(25, 32)]
    + [(32, 25, "g" + "B" * 12 + "g")]
)

_TILTED = [
    (21, 24, "g"),
    (22, 23, "ggg"),
    (23, 22, "ggpgg"),
    (24, 21, "ggpppgg"),
    (25, 20, "ggpppppgg"),
    (26, 19, "ggpppppppgg"),
    (27, 18, "ggpppppppppgg"),
    (28, 17, "gg" + "p" * 10),
    (29, 16, "gg" + "p" * 10),
    (30, 15, "gg" + "p" * 10),
    (31, 14, "gg" + "p" * 10),
    (32, 15, "gg" + "p" * 8),
    (33, 16, "gg" + "p" * 6),
    (34, 17, "gg" + "p" * 4),
    (35, 18, "gg" + "p" * 2),
    (36, 19, "gg"),
    (37, 20, "g"),
]


def _parse_action(action):
    """Accept action strings and common tuple/list representations."""
    if isinstance(action, (tuple, list)):
        name = str(action[0]).upper()
        if name == "MOUSE":
            if len(action) == 3:
                return name, (int(action[1]), int(action[2]))
            if len(action) == 2:
                return name, tuple(map(int, action[1]))
        return name, None

    text = str(action).strip()
    if text.upper().startswith("MOUSE"):
        numbers = re.findall(r"-?\d+", text)
        if len(numbers) >= 2:
            return "MOUSE", (int(numbers[0]), int(numbers[1]))
        return "MOUSE", None
    return text.upper(), None


def predict(board_lines, action):
    """
    Return the complete next board without modifying the input.

    Stateless, deterministic best-fit model: 19/20 supplied records.
    Transitions 4, 6, and 8 have identical inputs but conflicting
    outputs. This chooses the outcome shared by transitions 6 and 8.
    """
    if len(board_lines) != 64 or any(len(row) != 64 for row in board_lines):
        raise ValueError("Expected 64 strings, each containing 64 cells.")

    b = [list(row) for row in board_lines]
    name, mouse = _parse_action(action)

    tilted = b[21][24] == "g"
    shape = _TILTED if tilted else _UPRIGHT
    selected = "W" if "W" in board_lines[7][35:40] else "p"

    trailing_black = 64 - len(board_lines[63].rstrip("B"))
    tick = False

    def erase_container(raster):
        for r, c, text in raster:
            for offset, ch in enumerate(text):
                if ch != "B":
                    b[r][c + offset] = "B"

    def draw_container(raster, color):
        for r, c, text in raster:
            for offset, ch in enumerate(text):
                b[r][c + offset] = color if ch == "p" else ch

    def select_color(color):
        for c in range(35, 46):
            b[7][c] = "G"
        start = 35 if color == "W" else 41
        for c in range(start, start + 5):
            b[7][c] = "W"
        draw_container(shape, color)

    if name in ("UP", "DOWN"):
        tick = True

    elif name == "LEFT":
        if not tilted:
            erase_container(_UPRIGHT)
            draw_container(_TILTED, selected)
        tick = trailing_black <= 2

    elif name == "RIGHT":
        if tilted:
            erase_container(_TILTED)
            draw_container(_UPRIGHT, selected)

    elif name == "SPACE":
        changed = False
        for r in range(34, 39):
            for c in range(27, 37):
                if b[r][c] != selected:
                    changed = True
                b[r][c] = selected
        tick = changed

    elif name == "MOUSE" and mouse is not None:
        r, c = mouse
        if 2 <= r <= 6 and 35 <= c <= 39:
            select_color("W")
        elif 2 <= r <= 6 and 41 <= c <= 45:
            select_color("p")
            tick = True
        elif (r, c) == (28, 31):
            tick = True

    # UNDO and other unobserved actions conservatively do nothing.
    if tick:
        remaining = 64 - trailing_black
        if remaining > 0:
            b[63][remaining - 1] = "B"

    return ["".join(row) for row in b]
